{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE attr_span_kind='Client' AND span_name LIKE 'SELECT%' AND service_name IN ('ts-order-other-service','ts-order-service','ts-route-service','ts-train-service') GROUP BY 2,3 UNION ALL SELECT 'norm', service_name, span_name, COUNT(*), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE attr_span_kind='Client' AND span_name LIKE 'SELECT%' AND service_name IN ('ts-order-other-service','ts-order-service','ts-route-service','ts-train-service') GROUP BY 2,3 ORDER BY 3,1",
          "claim": "Only ts-order-other-service's SELECT ts.orders_other client spans slowed (p95 ~0.6ms to ~418ms); other services' DB calls stayed flat."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('OrderOtherRepository.findByAccountId','SELECT other.entity.Order','OrderOtherController.queryOrdersForRefresh','Transaction.commit') GROUP BY 1,2",
          "claim": "Inside order-other, the DB-bound repository and SELECT spans take ~420ms each, while the servlet/controller time is just their child time."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, AVG(value) avgv, MAX(value) maxv FROM abnormal_metrics WHERE service_name IN ('ts-order-other-service','mysql') AND metric='container.cpu.usage' GROUP BY 1,2",
          "claim": "Order-other and mysql container CPU stayed low during the incident, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-admin-order-service' AND attr_span_kind IN ('Client','Server') AND span_name LIKE '%adminorder%' GROUP BY 1,2,3 ORDER BY 2,3",
          "claim": "Admin-order client and server spans for adminorder endpoints slowed to ~1.7–2.3s, consistent with waiting on slow order-other calls."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%adminorderservice%' GROUP BY 2 UNION ALL SELECT 'norm', span_name, COUNT(*), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%adminorderservice%' GROUP BY 2 ORDER BY 2,1",
          "claim": "User-facing ui-dashboard adminorder GET latency rose from ~13ms to ~2230ms p95."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, COUNT(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%orderOtherService%' GROUP BY 2 UNION ALL SELECT 'norm', span_name, COUNT(*), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%orderOtherService%' GROUP BY 2 ORDER BY 2,1",
          "claim": "User-facing ui-dashboard orderOther refresh latency rose from ~2ms to ~422ms p95 with no error status.",
        }
      ]
    }
  ]
}
